import React, { useState, useEffect } from 'react';
import {
  Container,
  Typography,
  Paper,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Button,
  Box,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  TextField,
  Alert,
  IconButton,
} from '@mui/material';
import { Edit as EditIcon, Delete as DeleteIcon } from '@mui/icons-material';
import { institutionsAPI } from '../services/api';
import { useAuth } from '../context/AuthContext';

const ManageFaculties = () => {
  const { currentUser } = useAuth();
  const [faculties, setFaculties] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [dialogOpen, setDialogOpen] = useState(false);
  const [editingFaculty, setEditingFaculty] = useState(null);
  const [formData, setFormData] = useState({
    name: '',
    description: ''
  });

  useEffect(() => {
    fetchFaculties();
  }, []);

  const fetchFaculties = async () => {
    try {
      // For now, we'll simulate fetching faculties
      // In a real app, you'd fetch from an API endpoint like /api/institutions/faculties
      const mockFaculties = [
        { id: '1', name: 'Faculty of Science', description: 'Science and technology programs', courses: 5 },
        { id: '2', name: 'Faculty of Arts', description: 'Humanities and social sciences', courses: 3 }
      ];
      setFaculties(mockFaculties);
    } catch (error) {
      setError('Failed to load faculties');
    }
  };

  const handleOpenDialog = (faculty = null) => {
    if (faculty) {
      setEditingFaculty(faculty);
      setFormData({
        name: faculty.name,
        description: faculty.description
      });
    } else {
      setEditingFaculty(null);
      setFormData({
        name: '',
        description: ''
      });
    }
    setDialogOpen(true);
  };

  const handleCloseDialog = () => {
    setDialogOpen(false);
    setEditingFaculty(null);
    setFormData({
      name: '',
      description: ''
    });
    setError('');
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      setLoading(true);
      setError('');
      
      if (editingFaculty) {
        // Update faculty - simulate API call
        console.log('Updating faculty:', formData);
        // await institutionsAPI.updateFaculty(editingFaculty.id, formData);
        setSuccess('Faculty updated successfully!');
        
        // Update in local state
        setFaculties(prev => prev.map(f => 
          f.id === editingFaculty.id 
            ? { ...f, ...formData }
            : f
        ));
      } else {
        // Add new faculty - simulate API call
        console.log('Adding faculty:', formData);
        // const response = await institutionsAPI.addFaculty(formData);
        
        // Create new faculty with mock ID
        const newFaculty = {
          id: Date.now().toString(),
          ...formData,
          courses: 0
        };
        
        setSuccess('Faculty added successfully!');
        
        // Add to local state
        setFaculties(prev => [...prev, newFaculty]);
      }
      
      handleCloseDialog();
    } catch (error) {
      setError(error.response?.data?.error || 'Failed to save faculty');
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async (facultyId) => {
    if (window.confirm('Are you sure you want to delete this faculty? This will also delete all courses under this faculty.')) {
      try {
        // Simulate API call
        console.log('Deleting faculty:', facultyId);
        // await institutionsAPI.deleteFaculty(facultyId);
        
        setSuccess('Faculty deleted successfully!');
        
        // Remove from local state
        setFaculties(prev => prev.filter(f => f.id !== facultyId));
      } catch (error) {
        setError('Failed to delete faculty');
      }
    }
  };

  return (
    <Container maxWidth="lg" sx={{ mt: 4, mb: 4 }}>
      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 3 }}>
        <Typography variant="h4">
          Manage Faculties
        </Typography>
        <Button
          variant="contained"
          onClick={() => handleOpenDialog()}
        >
          Add New Faculty
        </Button>
      </Box>

      {error && (
        <Alert severity="error" sx={{ mb: 2 }} onClose={() => setError('')}>
          {error}
        </Alert>
      )}

      {success && (
        <Alert severity="success" sx={{ mb: 2 }} onClose={() => setSuccess('')}>
          {success}
        </Alert>
      )}

      <TableContainer component={Paper} elevation={3}>
        <Table sx={{ minWidth: 650 }} aria-label="faculties table">
          <TableHead sx={{ backgroundColor: 'primary.main' }}>
            <TableRow>
              <TableCell sx={{ color: 'white', fontWeight: 'bold' }}>Faculty Name</TableCell>
              <TableCell sx={{ color: 'white', fontWeight: 'bold' }}>Description</TableCell>
              <TableCell sx={{ color: 'white', fontWeight: 'bold' }}>Courses</TableCell>
              <TableCell sx={{ color: 'white', fontWeight: 'bold' }}>Actions</TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {faculties.length === 0 ? (
              <TableRow>
                <TableCell colSpan={4} align="center" sx={{ py: 4 }}>
                  <Typography variant="h6" color="textSecondary">
                    No faculties added yet
                  </Typography>
                  <Typography variant="body2" color="textSecondary" sx={{ mt: 1 }}>
                    Add your first faculty to get started
                  </Typography>
                </TableCell>
              </TableRow>
            ) : (
              faculties.map((faculty) => (
                <TableRow key={faculty.id}>
                  <TableCell component="th" scope="row" sx={{ fontWeight: 'bold' }}>
                    {faculty.name}
                  </TableCell>
                  <TableCell>{faculty.description}</TableCell>
                  <TableCell>{faculty.courses || 0} courses</TableCell>
                  <TableCell>
                    <Box sx={{ display: 'flex', gap: 1 }}>
                      <IconButton
                        color="primary"
                        onClick={() => handleOpenDialog(faculty)}
                        size="small"
                      >
                        <EditIcon />
                      </IconButton>
                      <IconButton
                        color="error"
                        onClick={() => handleDelete(faculty.id)}
                        size="small"
                      >
                        <DeleteIcon />
                      </IconButton>
                    </Box>
                  </TableCell>
                </TableRow>
              ))
            )}
          </TableBody>
        </Table>
      </TableContainer>

      {/* Add/Edit Faculty Dialog */}
      <Dialog 
        open={dialogOpen} 
        onClose={handleCloseDialog} 
        maxWidth="sm" 
        fullWidth
        disableEnforceFocus // Fix for the aria-hidden issue
      >
        <DialogTitle>
          {editingFaculty ? 'Edit Faculty' : 'Add New Faculty'}
        </DialogTitle>
        <form onSubmit={handleSubmit}>
          <DialogContent>
            <TextField
              autoFocus
              margin="dense"
              label="Faculty Name"
              fullWidth
              variant="outlined"
              value={formData.name}
              onChange={(e) => setFormData({ ...formData, name: e.target.value })}
              required
              disabled={loading}
            />
            <TextField
              margin="dense"
              label="Description"
              fullWidth
              variant="outlined"
              multiline
              rows={3}
              value={formData.description}
              onChange={(e) => setFormData({ ...formData, description: e.target.value })}
              sx={{ mt: 2 }}
              disabled={loading}
            />
          </DialogContent>
          <DialogActions>
            <Button onClick={handleCloseDialog} disabled={loading}>
              Cancel
            </Button>
            <Button type="submit" variant="contained" disabled={loading}>
              {loading ? 'Saving...' : (editingFaculty ? 'Update' : 'Add')} Faculty
            </Button>
          </DialogActions>
        </form>
      </Dialog>
    </Container>
  );
};

export default ManageFaculties;
